import 'package:render_runner/renderer_id.dart';
import 'package:test/test.dart';

const _sha = '6177616c5b7c14354e9410551a1acb2d31177ffb014e1289b6ae48571f0dd82b';

String _lock(String entry) =>
    '''
# Generated by pub
packages:
  other:
    dependency: transitive
    description:
      name: other
      sha256: "${'0' * 64}"
      url: "https://pub.dev"
    source: hosted
    version: "1.0.0"
  is_teams_reply:
$entry
sdks:
  dart: ">=3.13.0 <4.0.0"
''';

void main() {
  test("reads a pub.dev archive's sha256 as the id", () {
    final lock = _lock('''
    dependency: "direct main"
    description:
      name: is_teams_reply
      sha256: "$_sha"
      url: "https://pub.dev"
    source: hosted
    version: "0.1.0"''');
    expect(rendererIdFromLock(lock, 'is_teams_reply'), (id: _sha, why: null));
  });

  test('refuses a renderer from a path or git', () {
    final path = _lock('''
    dependency: "direct main"
    description:
      path: "../is_teams_reply"
      relative: true
    source: path
    version: "0.1.0"''');
    expect(
      rendererIdFromLock(path, 'is_teams_reply').why,
      'is_teams_reply comes from path, not an archive on pub.dev',
    );
    final git = _lock('''
    dependency: "direct main"
    description:
      path: "."
      ref: main
      resolved-ref: "${'a' * 40}"
      url: "https://github.com/intersyntactic/teams_module.git"
    source: git
    version: "0.1.0"''');
    expect(
      rendererIdFromLock(git, 'is_teams_reply').why,
      'is_teams_reply comes from git, not an archive on pub.dev',
    );
  });

  test('refuses another server, a missing hash, or a malformed one', () {
    String hosted(String url, String sha) => _lock('''
    dependency: "direct main"
    description:
      name: is_teams_reply
      sha256: "$sha"
      url: "$url"
    source: hosted
    version: "0.1.0"''');
    expect(
      rendererIdFromLock(
        hosted('https://pub.example', _sha),
        'is_teams_reply',
      ).id,
      isNull,
    );
    expect(
      rendererIdFromLock(
        hosted('https://pub.dev', _sha.toUpperCase()),
        'is_teams_reply',
      ).why,
      'is_teams_reply has no archive sha256 in the lockfile',
    );
  });

  test('refuses a package the lockfile does not hold, or no lockfile', () {
    expect(
      rendererIdFromLock(_lock('    source: hosted'), 'nope').why,
      'nope is not in the lockfile',
    );
    expect(rendererIdFromLock('{', 'x').why, startsWith('not a lockfile'));
  });
}
